// spec: .qa/e2e/specs/promo-filter.md
// seed: tests/seed.hunter_free.spec.ts
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.join(__dirname, '../../../auth/hunter_free.json') });

const SECTION = 'מסלול קידום והפצה';

test.describe('Promotion filter — jobs and tenders lists (#521d84)', () => {
  test('Choosing a value: count changes, URL ?promo=, removable chip @desktop @prod-safe #521d84', async ({ page }) => {
    const sidebar = page.getByRole('complementary');
    const section = sidebar.getByRole('button', { name: SECTION, exact: true });
    const option = (name: string) => sidebar.getByRole('checkbox', { name, exact: true });
    const chip = page.getByRole('button', { name: 'הסרת הסינון: קידום', exact: true });
    const count = page.getByText(/^\d+ תוצאות$/);
    const readCount = async () => Number((await count.innerText()).match(/\d+/)![0]);
    const cards = page.getByRole('main').getByRole('link', { name: /העתקת המספר J-\d+/ });

    // 1. Open /collaborations, note the count N and the page size
    await page.goto('/collaborations');
    await expect(count).toBeVisible();
    await expect(cards.first()).toBeVisible();
    const n = await readCount();
    const pageSize = await cards.count();

    // 2. «מסלול קידום והפצה» → «קידום»
    if ((await section.getAttribute('aria-expanded')) !== 'true') await section.click();
    await option('קידום').click();

    // Expected: promo= in URL, M ≤ N, «הכל» not selected, chip with «×» (AC3, AC4, AC7)
    await expect(page).toHaveURL(/[?&]promo=[^&]+/);
    await expect(option('קידום')).toBeChecked();
    await expect(option('הכל')).not.toBeChecked();
    await expect(chip).toBeVisible();
    await expect(chip).toContainText('×');
    await expect.poll(readCount).toBeLessThanOrEqual(n);
    const m = await readCount();
    // Number of cards on the page matches the count
    await expect(cards).toHaveCount(Math.min(m, pageSize));
    // Promoted jobs carry the «משרה חמה» badge
    await expect
      .poll(async () => (await cards.allInnerTexts()).filter((t) => !t.includes('משרה חמה')).length)
      .toBe(0);

    // 3. Click «×» on the chip «קידום»
    await chip.click();

    // Expected: chip gone, no promo in URL, «הכל» selected, count N again
    await expect(chip).toHaveCount(0);
    await expect.poll(() => new URL(page.url()).searchParams.has('promo')).toBe(false);
    await expect.poll(readCount).toBe(n);
    if ((await section.getAttribute('aria-expanded')) !== 'true') await section.click();
    await expect(option('הכל')).toBeChecked();
    await expect(option('קידום')).not.toBeChecked();
  });
});
